    if (k !== c.ok) { const b = m.opts.indexOf(c.ok); if (b >= 0) m.btn[b].fijo = "ok"; }
    m.fb = 1.2;
  };
  S.finMini = function (ok, resumen) {
    const m = S.m;
    m.fase = "res"; m.ok = ok;
    U.ev(ok ? "acierto" : "error");
