    S.espera = 0.5; S.esperaSoltar = true;
    setTxt(S.o.pj, ok ? "RESULTADO: BIEN\nLa Unidad sale fortalecida" : "RESULTADO: MAL\nLa Unidad paga las consecuencias");
    setTxt(S.o.texto, resumen);
