      }
    } else if (m.tipo === "consejo") {
      if (m.fb > 0) {
        m.fb -= dt;
        if (m.fb <= 0) {
          m.i++;
          if (m.i >= m.cs.length) return S.finMini(m.favor >= 3, "Votos a favor: " + m.favor + " de " + m.cs.length + " (mayoría: 3).");
