        }
        return;
      }
      let j = -1;
      if (kp[49]) j = 0; else if (kp[50]) j = 1; else if (kp[51]) j = 2;
      if (click) m.btn.forEach((b, k) => { if (hit(b, mx, my)) j = k; });
