    ];
    setTxt(U.mkTxt(A, "TxtTexto", 40, P.btn.y + 3 * P.btn.pitch + 10, 22, W - 80, { al: "center", col: "crema_osc", z: 910 }), "Esc, Enter o 1 para continuar · 2 opciones · 3 para salir");
