      else if (kd[39]) S.teclaDir = 1;
      else if (kd[38] && S.arribaDisp()) S.teclaDir = 2;
      else if (S.teclaDir) {
        const t = S.teclaDir; S.teclaDir = 0; S.dx = 0; S.dy = 0;
        return S.elegir(t === 2 ? S.c.arriba : t < 0 ? S.c.izq : S.c.der);
      }
